// Defining workflow transitions in external text files and parsing them at runtime
struct Transition {
    current_state: String,
    event: String,
    next_state: String,
}

fn handle_event(transitions: &[Transition], state: &mut String, event: &str) {
    if let Some(t) = transitions.iter().find(|t| t.current_state == *state && t.event == event) {
        *state = t.next_state.clone();
    }
}
