// Compiled, invariant-safe state transitions enforced by Rust's type-checker
pub enum OrderState {
    Created,
    Paid(PaymentDetails),
    Shipped,
}

impl OrderState {
    pub fn pay(self, details: PaymentDetails) -> Result<Self, &'static str> {
        match self {
            OrderState::Created => Ok(OrderState::Paid(details)),
            _ => Err("Invalid state transition"),
        }
    }
}
